<?php
declare(strict_types=1);
session_start();
$configFile = __DIR__ . '/config.php';
if (!file_exists($configFile)) { http_response_code(503); exit('Falta config.php. Seguí las instrucciones de README.txt.'); }
$config = require $configFile;
date_default_timezone_set($config['timezone'] ?? 'America/Argentina/Buenos_Aires');
try {
 $pdo = new PDO("mysql:host={$config['db_host']};dbname={$config['db_name']};charset=utf8mb4", $config['db_user'], $config['db_pass'], [
  PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC
 ]);
} catch (Throwable $e) { http_response_code(500); exit('No se pudo conectar a MySQL. Revisá config.php y los permisos de la base.'); }

function h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function check_csrf(): void { if(!hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '')) { http_response_code(400); exit('Solicitud inválida. Volvé a cargar la página.'); } }
function user(): ?array { return $_SESSION['user'] ?? null; }
function need_login(): void { if(!user()){ header('Location: ?'); exit; } }
function admin(): void { need_login(); if(user()['role']!=='admin'){ http_response_code(403); exit('Acceso solo para administradores.'); } }
function setting(PDO $db): array { return $db->query("SELECT * FROM settings WHERE id=1")->fetch() ?: []; }
function money($n, $currency='ARS'): string { return ($currency==='USD'?'US$ ':'$ ').number_format((float)$n,2,',','.'); }
function redirect(string $url='?'): never { header('Location: '.$url); exit; }

if (isset($_GET['logout'])) { session_destroy(); redirect(); }

if ($_SERVER['REQUEST_METHOD']==='POST') {
 $action=$_POST['action'] ?? '';
 if($action==='login') {
  check_csrf();
  $q=$pdo->prepare("SELECT * FROM users WHERE email=? AND active=1"); $q->execute([trim($_POST['email']??'')]); $u=$q->fetch();
  if($u && password_verify($_POST['password']??'', $u['password_hash'])) { session_regenerate_id(true); $_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']]; redirect('?page=dashboard'); }
  $error='Correo o contraseña incorrectos.';
 }
 if($action==='create_first_admin') {
  check_csrf();
  if((int)$pdo->query("SELECT COUNT(*) FROM users")->fetchColumn()!==0) exit('El administrador inicial ya existe.');
  $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $pass=$_POST['password']??'';
  if($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($pass)<10) $error='Completá los datos. La contraseña debe tener al menos 10 caracteres.';
  else { $q=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin')"); $q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]); $_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'admin']; redirect('?page=dashboard'); }
 }
 if($action==='save_client') { need_login(); check_csrf(); $id=(int)($_POST['id']??0); $d=[trim($_POST['name']??''),trim($_POST['tax_id']??''),trim($_POST['phone']??''),trim($_POST['email']??''),trim($_POST['address']??'')]; if($d[0]!==''){ if($id){$d[]=$id;$pdo->prepare("UPDATE clients SET name=?,tax_id=?,phone=?,email=?,address=? WHERE id=?")->execute($d);}else $pdo->prepare("INSERT INTO clients(name,tax_id,phone,email,address) VALUES(?,?,?,?,?)")->execute($d); } redirect('?page=clients'); }
 if($action==='save_catalog') { need_login(); check_csrf(); $id=(int)($_POST['id']??0); $d=[trim($_POST['description']??''),trim($_POST['unit']??'unidad'),(float)($_POST['price_ars']??0),(float)($_POST['price_usd']??0)]; if($d[0]!==''){ if($id){$d[]=$id;$pdo->prepare("UPDATE catalog SET description=?,unit=?,price_ars=?,price_usd=? WHERE id=?")->execute($d);}else $pdo->prepare("INSERT INTO catalog(description,unit,price_ars,price_usd) VALUES(?,?,?,?)")->execute($d); } redirect('?page=catalog'); }
 if($action==='save_user') { admin(); check_csrf(); $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$role=($_POST['role']??'employee')==='admin'?'admin':'employee'; if($name && filter_var($email,FILTER_VALIDATE_EMAIL) && strlen($pass)>=10){$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)")->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);} redirect('?page=users'); }
 if($action==='save_settings') { admin(); check_csrf(); $pdo->prepare("UPDATE settings SET company_name=?,tax_id=?,phone=?,email=?,address=?,quote_prefix=?,default_validity=?,notes=? WHERE id=1")->execute([trim($_POST['company_name']),trim($_POST['tax_id']),trim($_POST['phone']),trim($_POST['email']),trim($_POST['address']),trim($_POST['quote_prefix']),max(1,(int)$_POST['default_validity']),trim($_POST['notes'])]); redirect('?page=settings&saved=1'); }
 if($action==='save_quote') {
  need_login(); check_csrf();
  $client=(int)($_POST['client_id']??0); $currency=($_POST['currency']??'ARS')==='USD'?'USD':'ARS'; $rate=($_POST['exchange_rate']??'')!==''?(float)$_POST['exchange_rate']:null;
  $desc=$_POST['item_desc']??[];$qty=$_POST['item_qty']??[];$unit=$_POST['item_unit']??[];$price=$_POST['item_price']??[];
  $items=[];$subtotal=0;
  foreach($desc as $i=>$v){$v=trim($v);$q=(float)($qty[$i]??0);$p=(float)($price[$i]??0);if($v!==''&&$q>0){$line=round($q*$p,2);$subtotal+=$line;$items[]=[$v,$q,trim($unit[$i]??'unidad'),$p,$line];}}
  $discount=max(0,(float)($_POST['discount']??0));$total=max(0,$subtotal-$discount);
  if(!$client || !$items){$error='Seleccioná un cliente y cargá al menos un renglón válido.';}
  else {
   $s=setting($pdo);$num=$s['quote_prefix'].'-'.str_pad((string)$s['next_quote_number'],6,'0',STR_PAD_LEFT);
   $pdo->beginTransaction();
   $pdo->prepare("INSERT INTO quotes(number,client_id,created_by,currency,exchange_rate,issue_date,valid_until,status,notes,subtotal,discount,total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$num,$client,user()['id'],$currency,$rate,$_POST['issue_date']?:date('Y-m-d'),$_POST['valid_until']?:null,$_POST['status']??'borrador',trim($_POST['notes']??''),$subtotal,$discount,$total]);
   $qid=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO quote_items(quote_id,description,quantity,unit,unit_price,line_total) VALUES(?,?,?,?,?,?)");foreach($items as $it)$ins->execute([$qid,...$it]);
   $pdo->exec("UPDATE settings SET next_quote_number=next_quote_number+1 WHERE id=1");$pdo->commit();redirect('?page=quote&id='.$qid);
  }
 }
 if($action==='status') { need_login(); check_csrf(); $pdo->prepare("UPDATE quotes SET status=? WHERE id=?")->execute([$_POST['status'],(int)$_POST['id']]); redirect('?page=quotes'); }
}

$page=$_GET['page']??(user()?'dashboard':'login');
$settings=setting($pdo);
if(!user() && $page!=='login') $page='login';
if(user() && $page==='login') $page='dashboard';
$first=(int)$pdo->query("SELECT COUNT(*) FROM users")->fetchColumn()===0;
