<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=h($title)?> · FG Presupuestos</title><link rel="stylesheet" href="assets/style.css"></head><body>
<?php if(user()): ?><aside class="sidebar"><div class="brand">FG <span>Presupuestos</span></div><nav><a href="?page=dashboard">▦ <span>Inicio</span></a><a href="?page=quotes">▤ <span>Presupuestos</span></a><a href="?page=clients">♙ <span>Clientes</span></a><a href="?page=catalog">▣ <span>Servicios y materiales</span></a><?php if(user()['role']==='admin'): ?><a href="?page=users">♧ <span>Usuarios</span></a><a href="?page=settings">⚙ <span>Empresa</span></a><?php endif; ?></nav><div class="sidebottom"><?=h(user()['name'])?><a href="?logout=1">Cerrar sesión</a></div></aside><?php endif; ?>
<main class="<?=user()?'main':''?>"><?php if(user()): ?><header class="top"><strong><?=h($settings['company_name']??'FG Servicios e Instalaciones')?></strong><span><?=h(user()['role']==='admin'?'Administrador':'Empleado')?></span></header><?php endif; ?><section class="content">
<?php }
function footer_html(){ ?></section></main></body></html><?php }
if($page==='login' && !$first){ header_html('Ingresar',$settings); ?>
<div class="login-wrap"><div class="login-card"><div class="brand dark">FG <span>Presupuestos</span></div><h1>Ingresar</h1><p>Administración de presupuestos</p><?php if(!empty($error)): ?><div class="alert"><?=h($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="action" value="login"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Correo electrónico</label><input type="email" name="email" required><label>Contraseña</label><input type="password" name="password" required><button class="btn primary full">Ingresar</button></form></div></div>
