if($first){ header_html('Configuración inicial',$settings); ?><div class="login-wrap"><div class="login-card"><div class="brand dark">FG <span>Presupuestos</span></div><h1>Crear administrador</h1><p>Este paso se realiza una sola vez.</p><?php if(!empty($error)): ?><div class="alert"><?=h($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="action" value="create_first_admin"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Nombre</label><input name="name" required><label>Correo electrónico</label><input type="email" name="email" required><label>Contraseña (mínimo 10 caracteres)</label><input type="password" name="password" minlength="10" required><button class="btn primary full">Crear administrador</button></form></div></div><?php footer_html(); exit; }

need_login();
header_html(ucfirst($page),$settings);
if($page==='dashboard'){
 $stats=$pdo->query("SELECT COUNT(*) total, SUM(status='aprobado') approved, SUM(status='pendiente') pending, SUM(total) amount FROM quotes")->fetch();
 $recent=$pdo->query("SELECT q.*,c.name client FROM quotes q JOIN clients c ON c.id=q.client_id ORDER BY q.id DESC LIMIT 8")->fetchAll(); ?>
