<?php } elseif($page==='catalog'){ $rows=$pdo->query("SELECT * FROM catalog WHERE active=1 ORDER BY description")->fetchAll(); ?>
<h1>Servicios y materiales</h1><div class="panel"><h2>Agregar al catálogo</h2><form method="post" class="gridform"><input type="hidden" name="action" value="save_catalog"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input name="description" placeholder="Descripción" required><input name="unit" placeholder="Unidad (unidad, hora, metro)"><input type="number" step=".01" name="price_ars" placeholder="Precio ARS"><input type="number" step=".01" name="price_usd" placeholder="Precio USD"><button class="btn primary">Guardar ítem</button></form></div><div class="panel tablewrap"><table><tr><th>Descripción</th><th>Unidad</th><th>Precio ARS</th><th>Precio USD</th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r['description'])?></td><td><?=h($r['unit'])?></td><td><?=money($r['price_ars'])?></td><td><?=money($r['price_usd'],'USD')?></td></tr><?php endforeach; ?></table></div>
<?php } elseif($page==='new_quote'){
 $clients=$pdo->query("SELECT id,name FROM clients ORDER BY name")->fetchAll();$catalog=$pdo->query("SELECT * FROM catalog WHERE active=1 ORDER BY description")->fetchAll(); ?>
<h1>Nuevo presupuesto</h1><?php if(!empty($error)): ?><div class="alert"><?=h($error)?></div><?php endif; ?><form method="post" class="panel" id="quoteForm"><input type="hidden" name="action" value="save_quote"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="gridform"><label>Cliente<select name="client_id" required><option value="">Seleccionar cliente</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>"><?=h($c['name'])?></option><?php endforeach; ?></select></label><label>Moneda<select name="currency" id="currency"><option value="ARS">Pesos argentinos (ARS)</option><option value="USD">Dólares (USD)</option></select></label><label>Fecha<input type="date" name="issue_date" value="<?=date('Y-m-d')?>"></label><label>Válido hasta<input type="date" name="valid_until" value="<?=date('Y-m-d',strtotime('+15 days'))?>"></label><label>Tipo de cambio (opcional)<input type="number" step=".0001" name="exchange_rate" placeholder="ARS por USD"></label><label>Estado<select name="status"><option value="borrador">Borrador</option><option value="enviado">Enviado</option></select></label></div><h2>Detalle</h2><datalist id="catalog"><?php foreach($catalog as $c): ?><option value="<?=h($c['description'])?>" data-ars="<?=$c['price_ars']?>" data-usd="<?=$c['price_usd']?>"><?php endforeach; ?></datalist><div id="items"><div class="itemrow"><input name="item_desc[]" list="catalog" placeholder="Descripción del trabajo o material" required><input name="item_qty[]" type="number" min=".01" step=".01" value="1" placeholder="Cant."><input name="item_unit[]" value="unidad" placeholder="Unidad"><input name="item_price[]" type="number" min="0" step=".01" value="0" placeholder="Precio unitario"><button type="button" class="btn danger" onclick="this.parentElement.remove();calc()">×</button></div></div><button type="button" class="btn" onclick="addItem()">+ Agregar renglón</button><div class="gridform totals"><label>Descuento<input type="number" name="discount" id="discount" value="0" min="0" step=".01" oninput="calc()"></label><div class="totalbox">Total estimado <strong id="totalPreview">$ 0,00</strong></div></div><label>Observaciones / condiciones<textarea name="notes" rows="3"></textarea></label><button class="btn primary">Guardar presupuesto</button></form><script>function addItem(){document.getElementById('items').insertAdjacentHTML('beforeend',`<div class="itemrow"><input name="item_desc[]" list="catalog" placeholder="Descripción" required><input name="item_qty[]" type="number" min=".01" step=".01" value="1"><input name="item_unit[]" value="unidad"><input name="item_price[]" type="number" min="0" step=".01" value="0" oninput="calc()"><button type="button" class="btn danger" onclick="this.parentElement.remove();calc()">×</button></div>`)}function calc(){let t=0;document.querySelectorAll('.itemrow').forEach(r=>{t+=(parseFloat(r.querySelector('[name="item_qty[]"]').value)||0)*(parseFloat(r.querySelector('[name="item_price[]"]').value)||0)});t-=parseFloat(document.getElementById('discount').value)||0;let cur=document.getElementById('currency').value;document.getElementById('totalPreview').textContent=(cur==='USD'?'US$ ':'$ ')+Math.max(0,t).toLocaleString('es-AR',{minimumFractionDigits:2})}document.getElementById('quoteForm').addEventListener('input',calc);</script>
