<?php }}
elseif($page==='users'){ admin();$rows=$pdo->query("SELECT id,name,email,role,active,created_at FROM users ORDER BY id")->fetchAll(); ?><h1>Usuarios</h1><div class="panel"><h2>Crear usuario</h2><form method="post" class="gridform"><input type="hidden" name="action" value="save_user"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input name="name" placeholder="Nombre" required><input type="email" name="email" placeholder="Correo" required><input type="password" name="password" placeholder="Contraseña (mín. 10 caracteres)" minlength="10" required><select name="role"><option value="employee">Empleado</option><option value="admin">Administrador</option></select><button class="btn primary">Crear usuario</button></form></div><div class="panel tablewrap"><table><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Activo</th></tr><?php foreach($rows as $u): ?><tr><td><?=h($u['name'])?></td><td><?=h($u['email'])?></td><td><?=h($u['role'])?></td><td><?= $u['active']?'Sí':'No'?></td></tr><?php endforeach; ?></table></div>
