function table_quotes($rows){ ?>
<div class="panel tablewrap"><table><tr><th>Número</th><th>Fecha</th><th>Cliente</th><th>Estado</th><th>Total</th><th></th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r['number'])?></td><td><?=h($r['issue_date'])?></td><td><?=h($r['client'])?></td><td><span class="pill"><?=h($r['status'])?></span></td><td><?=money($r['total'],$r['currency'])?></td><td><a href="?page=quote&id=<?=$r['id']?>">Ver / PDF</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6">Todavía no hay presupuestos.</td></tr><?php endif; ?></table></div>
<?php }
